def maximum_sum_after_negations(nums, k):
 nums=sorted(nums)
 for i in range(len(nums)):
  if k and nums[i]<0:nums[i]=-nums[i];k-=1
 if k%2:nums[nums.index(min(nums))]*=-1
 return sum(nums)

